appearances.css:
.app{padding:4px;border-radius:6px;display:flex;flex-wrap:wrap;gap:4px;align-items:stretch;font-size:10px}
.row{margin:0;gap:4px;flex:0 0 auto}
.row:nth-child(1){flex:1 1 auto;order:1}
.row:nth-child(1) .control{padding:0;border:0;gap:1px;flex:1 1 0}
.row:nth-child(1) .control:first-child{flex:2 1 0}
.row:nth-child(1) .control:not(:first-child){flex:1.3 1 0}
.row:nth-child(1) select{font-size:9px;padding:3px 2px}
.grid{display:contents}
.sec{display:flex;flex-wrap:nowrap;gap:0;padding:3px 3px 4px;border:1px solid var(--line,#344953);border-radius:4px;min-width:0}
.sec[data-group=filter]{order:3;flex:0 0 92px}
.sec[data-group=osc]{order:4;flex:4 1 192px}
.sec[data-group=out]{order:5;flex:3 1 144px}
.sec[data-group=dynamics]{order:6;flex:1 1 100%}
.row:nth-child(3),.row:nth-child(4){order:2}
.row button{font-size:9px;padding:4px 7px}
.control{padding:0;border:0;flex:1 1 0;align-items:center;gap:0;text-align:center;display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-content:start;min-width:0}
.control>span:not(.kn){order:3;font-size:7.5px;letter-spacing:-.03em;line-height:1.1;text-align:center;max-width:100%}
.control>output{order:2;font-size:8px;line-height:1.1;white-space:nowrap}
.control .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
.row:nth-child(1) .control>span{order:0;font-size:8px;margin-bottom:1px}
